@page{margin:26px 32px}body{font-family:'DejaVu Sans',sans-serif;color:#111;font-size:9.5px;line-height:1.3}table{border-collapse:collapse;width:100%}td,th{border:1px solid #333;padding:3px;vertical-align:top}h1{font-size:11px;text-align:center;margin:6px 0}p{margin:7px 0}.print-header{page-break-inside:avoid;margin-bottom:18px}.print-letterhead{position:relative;height:183px;overflow:hidden;margin-bottom:16px}.print-letterhead img{position:absolute;top:0;left:0;width:100%}.meta{width:85.5%;margin:0 auto;font-family:"Times-Roman","Times New Roman",serif;font-size:12px;line-height:1.1}.meta td{border:0.5pt solid #000;padding:2px 7px;vertical-align:middle}.meta .meta-logo{width:41.3%;text-align:center;padding:10px}.meta-logo img{width:94%;max-width:224px;height:auto}.meta .meta-institution{text-align:center;font-size:14px;font-weight:bold;white-space:nowrap}.meta .meta-label{width:23%;border-right:0;white-space:nowrap}.meta .meta-colon{width:3%;padding-left:0;padding-right:0;border-left:0;border-right:0}.meta .meta-value{border-left:0;white-space:nowrap}.meta .meta-title{padding:3px 8px}.meta-title h1{font-family:"Times-Roman","Times New Roman",serif;font-size:11.5px;line-height:1.12;margin:0;text-align:center;font-weight:bold}.criteria th{background:#eee}.criteria tr{page-break-inside:avoid}.signatures td{border:0;text-align:center;width:50%}.signatures img{height:38px;max-width:180px}.signoff{page-break-inside:avoid}.page{page-break-before:always}.evidence{max-width:100%;max-height:330px}.caption{font-size:9px;color:#555}footer{font-size:8px;color:#666;margin-top:10px}
.meta .meta-content{padding:0;width:58.7%}.meta-details{width:100%;font-family:inherit;font-size:inherit;line-height:1.1}.meta-details td{border-left:0;border-right:0}.meta-details tr:first-child td{border-top:0}.meta-details tr:last-child td{border-bottom:0}.meta-details .meta-label{width:34%}.meta-details .meta-colon{width:5%}

.attachments{margin-top:18px}.attachment-group{page-break-inside:avoid;margin:16px 0}
